export const sweepTriggers = pgTable("sweep_triggers", {
  id: serial("id").primaryKey(),
  customerId: varchar("customerId", { length: 255 }).notNull(),
  triggerType: varchar("triggerType", { length: 50 }).notNull(),
  priority: varchar("priority", { length: 50 }).notNull(),
  reasons: json("reasons").notNull(),
  affectedSurfaces: integer("affectedSurfaces").notNull(),
  coverageAtTrigger: real("coverageAtTrigger"),
  status: varchar("status", { length: 50 }).default("pending").notNull(),
  surfacesReviewed: integer("surfacesReviewed").default(0),
  surfacesRemediated: integer("surfacesRemediated").default(0),
  durationMs: integer("durationMs"),
  completedAt: timestamp("completedAt"),
  createdAt: timestamp("createdAt").defaultNow().notNull(),
}, (table) => [
  index("idx_st_customerId").on(table.customerId),
  index("idx_st_status").on(table.status),
  index("idx_st_priority").on(table.priority),
  index("idx_st_createdAt").on(table.createdAt),
]);

export type SweepTrigger = typeof sweepTriggers.$inferSelect;
