/**
 * Trigger a sweep run and store it in the database.
 */
export async function triggerSweep(customerId: string, evaluation: SweepEvaluation, triggerType: 'manual' | 'scheduled'): Promise<SweepResult> {
  const db = await getDb();
  if (!db) throw new Error('Database unavailable');

  const startTime = Date.now();

  // Store the trigger record. The row's serial id IS the sweep id — SweepResult
  // and the remediation gate both identify a sweep by that number.
  const [trigger] = await db.insert(sweepTriggers).values({
    customerId,
    triggerType,
    status: 'triggered',
    priority: evaluation.priority,
    reasons: evaluation.reasons,
    affectedSurfaces: evaluation.affectedSurfaces,
    coverageAtTrigger: evaluation.coverageAtEvaluation,
  }).returning({ id: sweepTriggers.id });
  const sweepId = trigger.id;

  log.info({ customerId, sweepId, triggerType, priority: evaluation.priority }, 'Sweep triggered, starting remediation...');

  // Get all active surfaces for the customer
  const surfacesToSweep = await db.select().from(discoveredSurfaces).where(
    and(
      eq(discoveredSurfaces.customerId, customerId),
      inArray(discoveredSurfaces.status, ['new', 'stale', 'reviewed'])
    )
  );

  if (surfacesToSweep.length === 0) {
    log.warn({ customerId, sweepId }, 'Sweep triggered but no active surfaces found to process.');
    const result: SweepResult = { sweepId, surfacesReviewed: 0, surfacesRemediated: 0, issuesFound: 0, durationMs: Date.now() - startTime };
    await db.update(sweepTriggers)
      .set({ status: 'completed', surfacesReviewed: 0, surfacesRemediated: 0, durationMs: result.durationMs, completedAt: new Date() })
      .where(eq(sweepTriggers.id, sweepId));
    return result;
  }

  // Map to the remediation-gate input shape. The stored snapshot is the content
  // under review; lastScore is the most recent score recorded for the surface.
  const remediationInputs = surfacesToSweep.map(surface => ({
    surfaceId: surface.surfaceId,
    surfaceUrl: surface.url,
    content: surface.contentSnapshot || '',
    reviewResult: {
      score: surface.lastScore ?? 0,
      issues: [],
      patches: [],
      block_release: false,
    },
  }));

  log.info({
    customerId,
    sweepId,
    surfaces: remediationInputs.length,
    shieldTypes: [...new Set(surfacesToSweep.map(s => mapSurfaceTypeToShieldType(s.surfaceType)))],
  }, 'Sweeping surfaces through the Gravito-gated remediation pipeline');

  // Get business truth context — a prompt-ready string the remediator embeds
  const truthContext = getBusinessTruthContext();

  // Execute remediation behind the Gravito gate
  let gateOutcome: Awaited<ReturnType<typeof gatedRemediateSweepResults>>;
  try {
    gateOutcome = await gatedRemediateSweepResults(sweepId, customerId, remediationInputs, truthContext);
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error({ customerId, sweepId, error: errMsg }, 'Remediation sweep failed');
    const result: SweepResult = { sweepId, surfacesReviewed: 0, surfacesRemediated: 0, issuesFound: 0, durationMs: Date.now() - startTime };
    await db.update(sweepTriggers)
      .set({ status: 'failed', surfacesReviewed: 0, surfacesRemediated: 0, durationMs: result.durationMs, completedAt: new Date() })
      .where(eq(sweepTriggers.id, sweepId));
    return result;
  }

  // Post-process results (e.g., update surface status)
  const errors: string[] = [];
  for (const res of gateOutcome.results) {
    if (!res.accepted) {
      errors.push(`Surface ${res.surfaceId}: remediation ${res.gateDecision}`);
      continue;
    }
    await db.update(discoveredSurfaces)
      .set({ status: 'reviewed', lastSeen: new Date() })
      .where(and(eq(discoveredSurfaces.surfaceId, res.surfaceId), eq(discoveredSurfaces.customerId, customerId)));
  }

  const result: SweepResult = {
    sweepId,
    surfacesReviewed: gateOutcome.totalSurfaces,
    surfacesRemediated: gateOutcome.accepted,
    issuesFound: errors.length,
    durationMs: Date.now() - startTime,
  };
